function evidence = f90_xmed09_extract_reference_evidence(modelPath, officialScenarios, outDir)
% Extract complete evidence from the exact bundled CVS-LVAD reference without saving it.
arguments
    modelPath (1,1) string
    officialScenarios (1,1) string
    outDir (1,1) string
end

expectedModelPresence = "present";
expectedInitializerPresence = "present";
assert(isfile(modelPath) && lower(localFilePresence(modelPath)) == expectedModelPresence, ...
    "SimuVerity:F90:XMED09:ReferenceIdentity", ...
    "Bundled reference model is missing or binding-mismatched.");
sourceRoot = string(fileparts(modelPath));
initPath = fullfile(sourceRoot, "SimMDL_Parameters.m");
assert(isfile(initPath) && lower(localFilePresence(initPath)) == expectedInitializerPresence, ...
    "SimuVerity:F90:XMED09:InitializerIdentity", ...
    "Bundled reference initializer is missing or binding-mismatched.");
assert(isfile(officialScenarios), "SimuVerity:F90:XMED09:OfficialScenarios", ...
    "Official scenario contract is missing.");
official = jsondecode(fileread(officialScenarios));
assert(string(official.task_id) == "F90-XMED-09" && ...
    isfield(official, "scenarios") && isfield(official, "simulation"), ...
    "SimuVerity:F90:XMED09:OfficialScenarios", ...
    "Official scenario contract is invalid.");
scenarios = official.scenarios;
expectedIds = ["nominal_impaired_sliding", "healthy_assisted", ...
    "impaired_unassisted", "pid_assist", "baroreflex_disabled", ...
    "fixed_resistance_elastance"];
assert(numel(scenarios) == numel(expectedIds) && ...
    isequal(string({scenarios.id}), expectedIds), ...
    "SimuVerity:F90:XMED09:OfficialScenarios", ...
    "Official scenario identities are missing or reordered.");
simulation = official.simulation;
assert(double(simulation.stop_time_s) == 60.0 && ...
    double(simulation.evidence_points) == 1501, ...
    "SimuVerity:F90:XMED09:OfficialScenarios", ...
    "Official simulation contract is changed.");
if ~isfolder(outDir), mkdir(outDir); end

evidence = struct("schema", "simuverity.formal90-fixed-evidence.v1", ...
    "task_id", "F90-XMED-09", "evaluation_subject", "reference", ...
    "matlab_release", version("-release"), "started_at", localNow, ...
    "finished_at", "", "source_model", string(modelPath), ...
    "source_model_file_presence", localFilePresence(modelPath), ...
    "initializer_file_presence", localFilePresence(initPath), ...
    "load_pass", false, "update_pass", false, "compile_pass", false, ...
    "evidence_complete", false, "static_audit", struct, ...
    "scenarios", [], "errors", struct);

originalDir = pwd;
originalPath = path;
cleanup = onCleanup(@() localRestore(originalDir, originalPath)); %#ok<NASGU>
try
    cd(sourceRoot);
    addpath(sourceRoot, "-begin");
    load_system(modelPath);
    model = "CVS_LVAD_2021a";
    evidence.load_pass = true;
    set_param(model, "SimulationMode", "normal", "LimitDataPoints", "off");
    localInstallTaps(model);
    localInitialize(initPath);
    evidence.static_audit = localStaticAudit(model, sourceRoot);
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;

    rows = repmat(localEmptyScenario, numel(scenarios), 1);
    for k = 1:numel(scenarios)
        rows(k).id = string(scenarios(k).id);
        rows(k).requested_inputs = scenarios(k);
        try
            localInitialize(initPath);
            localApplyScenario(model, scenarios(k));
            simIn = Simulink.SimulationInput(model);
            simIn = simIn.setModelParameter("SimulationMode", "normal", ...
                "StopTime", sprintf("%.17g", simulation.stop_time_s), ...
                "ReturnWorkspaceOutputs", "on");
            started = tic;
            evalc("simOut = sim(simIn);");
            rows(k).simulation_wall_clock_s = toc(started);
            rows(k).outputs = localExtractOutputs(simOut, simulation);
            rows(k).metrics = localMetrics(rows(k).outputs, scenarios(k));
            rows(k).simulation_pass = true;
            rows(k).required_evidence_pass = localOutputsValid( ...
                rows(k).outputs, simulation.stop_time_s);
            rows(k).valid = rows(k).required_evidence_pass;
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
    evidence.evidence_complete = evidence.load_pass && evidence.update_pass && ...
        evidence.compile_pass && all([rows.valid]) && ...
        strcmpi(evidence.source_model_file_presence, localFilePresence(modelPath)) && ...
        strcmpi(evidence.initializer_file_presence, localFilePresence(initPath));
catch ME
    evidence.errors.session = localError(ME);
end
evidence.finished_at = localNow;
localCloseAll;
localWriteJson(fullfile(outDir, "evidence.json"), evidence);
fprintf("F90_XMED09_EVIDENCE complete=%d valid=%d/%d path=%s\n", ...
    evidence.evidence_complete, localValidCount(evidence.scenarios), ...
    numel(evidence.scenarios), fullfile(outDir, "evidence.json"));
end

function localInitialize(initPath)
command = "run('" + replace(string(initPath), "'", "''") + "')";
evalin("base", command);
end

function localApplyScenario(model, scenario)
set_param(model + "/0-Healthy, 1-Sick", "Value", sprintf("%d", scenario.CardiacConditionMode));
set_param(model + "/0-Disconnect, 1-Connect", "Value", sprintf("%d", scenario.LVADConnected));
set_param(model + "/0-PID, 1-Sliding-Mode", "Value", sprintf("%d", scenario.AssistControllerMode));
set_param(model + "/0=Off 1=On", "Value", sprintf("%d", scenario.BaroreflexEnabled));
set_param(model + "/0=Constant 1=vary", "Value", sprintf("%d", scenario.ResistanceVariationEnabled));
set_param(model + "/0=Constant 1=vary1", "Value", sprintf("%d", scenario.ElastanceVariationEnabled));
end

function localInstallTaps(model)
sources = ["From16", "From9", "From8", "From13", ...
    "From17", "From14", "From1", "From15", ...
    "From2", "From6", "From7", "From11"];
variables = ["f90_psai", "f90_pao", "f90_plv", "f90_vlv", ...
    "f90_pe", "f90_control_effort", "f90_iae", "f90_itae", ...
    "f90_pra", "f90_prv", "f90_pla", "f90_vrv"];
for k = 1:numel(sources)
    localTap(model, model + "/" + sources(k), variables(k));
end
end

function localTap(parent, source, variable)
tap = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(tap) < 0, "SimuVerity:F90:XMED09:TapCollision", ...
    "Temporary tap already exists: %s", tap);
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries", ...
    "MaxDataPoints", "inf");
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
assert(~isempty(sourcePorts.Outport) && sourcePorts.Outport(1) > 0, ...
    "SimuVerity:F90:XMED09:TapPort", "Missing output port on %s", source);
add_line(parent, sourcePorts.Outport(1), tapPorts.Inport(1), "autorouting", "on");
end

function outputs = localExtractOutputs(simOut, simulation)
names = ["f90_psai", "f90_pao", "f90_plv", "f90_vlv", ...
    "f90_pe", "f90_control_effort", "f90_iae", "f90_itae", ...
    "f90_pra", "f90_prv", "f90_pla", "f90_vrv"];
series = cell(size(names));
for k = 1:numel(names), series{k} = localSeries(simOut, names(k)); end
startTime = max(cellfun(@(x) x.time(1), series));
endTime = min(cellfun(@(x) x.time(end), series));
assert(endTime > startTime, "SimuVerity:F90:XMED09:Overlap", ...
    "Required signals have no common time interval.");
time = linspace(startTime, endTime, simulation.evidence_points)';
values = zeros(numel(time), numel(series));
for k = 1:numel(series), values(:,k) = localInterp(series{k}, time); end
outputs = struct("time_s", time, "HemodynamicState", values(:,1:4), ...
    "AssistControlState", values(:,5:8), "ChamberState", values(:,9:12));
end

function metrics = localMetrics(outputs, scenario)
t = outputs.time_s;
h = outputs.HemodynamicState;
a = outputs.AssistControlState;
c = outputs.ChamberState;
tail = t >= max(t(1), t(end) - 20);
psai = h(:,1); pao = h(:,2); plv = h(:,3); vlv = h(:,4);
metrics = struct( ...
    "systemic_pressure_tail_mean_mmHg", mean(psai(tail)), ...
    "systemic_pressure_tail_min_mmHg", min(psai(tail)), ...
    "systemic_pressure_tail_max_mmHg", max(psai(tail)), ...
    "systemic_pressure_tail_pulsatility_mmHg", max(psai(tail)) - min(psai(tail)), ...
    "systemic_target_tail_mae_mmHg", mean(abs(psai(tail) - 75.0)), ...
    "aortic_pressure_tail_mean_mmHg", mean(pao(tail)), ...
    "left_ventricular_pressure_min_mmHg", min(plv), ...
    "left_ventricular_pressure_max_mmHg", max(plv), ...
    "left_ventricular_volume_min_mL", min(vlv), ...
    "left_ventricular_volume_max_mL", max(vlv), ...
    "left_ventricular_volume_excursion_mL", max(vlv(tail)) - min(vlv(tail)), ...
    "assist_pressure_tail_mean_mmHg", mean(a(tail,1)), ...
    "assist_pressure_tail_span_mmHg", max(a(tail,1)) - min(a(tail,1)), ...
    "controller_effort_tail_rms", sqrt(mean(a(tail,2).^2)), ...
    "controller_effort_tail_span", max(a(tail,2)) - min(a(tail,2)), ...
    "iae_final", a(end,3), "itae_final", a(end,4), ...
    "right_atrial_pressure_min_mmHg", min(c(:,1)), ...
    "right_atrial_pressure_max_mmHg", max(c(:,1)), ...
    "right_ventricular_pressure_min_mmHg", min(c(:,2)), ...
    "right_ventricular_pressure_max_mmHg", max(c(:,2)), ...
    "left_atrial_pressure_min_mmHg", min(c(:,3)), ...
    "left_atrial_pressure_max_mmHg", max(c(:,3)), ...
    "right_ventricular_volume_min_mL", min(c(:,4)), ...
    "right_ventricular_volume_max_mL", max(c(:,4)), ...
    "hemodynamic_summary", sum(abs(diff(h(:,[1,3,4]),1,1)), "all"), ...
    "assist_summary", sum(abs(diff(a(:,1:2),1,1)), "all"), ...
    "all_finite", all(isfinite([h(:); a(:); c(:)])));
end

function pass = localOutputsValid(outputs, stopTime)
t = outputs.time_s;
pass = numel(t) >= 100 && all(isfinite(t)) && all(diff(t) > 0) && ...
    t(1) <= 1e-9 && t(end) >= stopTime - 1e-3 && ...
    isequal(size(outputs.HemodynamicState), [numel(t), 4]) && ...
    isequal(size(outputs.AssistControlState), [numel(t), 4]) && ...
    isequal(size(outputs.ChamberState), [numel(t), 4]) && ...
    all(isfinite([outputs.HemodynamicState(:); ...
    outputs.AssistControlState(:); outputs.ChamberState(:)]));
end

function audit = localStaticAudit(model, sourceRoot)
allBlocks = find_system(model, "FollowLinks", "off", "LookUnderMasks", "all");
subsystems = find_system(model, "FollowLinks", "off", "LookUnderMasks", "all", ...
    "BlockType", "SubSystem");
dynamic = find_system(model, "FollowLinks", "off", "LookUnderMasks", "all", ...
    "Regexp", "on", "BlockType", "Integrator|DiscreteIntegrator|StateSpace|S-Function|Memory|UnitDelay");
required = [model + "/Heart+LVAD1", model + "/Processing_for_control", ...
    model + "/Controller", model + "/Ursino Model"];
audit = struct("recursive_block_count", numel(allBlocks), ...
    "subsystem_count", numel(subsystems), "dynamic_block_count", numel(dynamic), ...
    "heart_lvad_present", getSimulinkBlockHandle(required(1)) > 0, ...
    "control_processing_present", getSimulinkBlockHandle(required(2)) > 0, ...
    "controller_present", getSimulinkBlockHandle(required(3)) > 0, ...
    "baroreflex_present", getSimulinkBlockHandle(required(4)) > 0, ...
    "measured_pressure_tag_present", localTagPresent(model, "From", "Psai"), ...
    "assist_pressure_tag_present", localTagPresent(model, "From", "Pe"), ...
    "control_effort_tag_present", localTagPresent(model, "From", "Control_Effort"), ...
    "initializer_present", isfile(fullfile(sourceRoot, "SimMDL_Parameters.m")));
end

function pass = localTagPresent(model, blockType, tag)
blocks = find_system(model, "SearchDepth", 1, "BlockType", blockType);
pass = false;
for k = 1:numel(blocks)
    if strcmp(get_param(blocks{k}, "GotoTag"), tag), pass = true; return; end
end
end

function series = localSeries(simOut, name)
try, value = simOut.get(name); catch, value = []; end
if isempty(value) && evalin("base", sprintf("exist('%s','var')", name))
    value = evalin("base", name);
end
assert(isa(value, "timeseries"), "SimuVerity:F90:XMED09:MissingSignal", ...
    "Required Timeseries %s is missing.", name);
time = double(value.Time(:));
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data,1) ~= numel(time) && size(data,2) == numel(time), data = data.'; end
assert(size(data,1) == numel(time) && size(data,2) == 1, ...
    "SimuVerity:F90:XMED09:SignalShape", "Unexpected shape for %s.", name);
[time, index] = unique(time, "stable"); data = data(index,:);
assert(numel(time) >= 2 && all(isfinite(time)) && all(isfinite(data)), ...
    "SimuVerity:F90:XMED09:SignalInvalid", "Invalid signal %s.", name);
series = struct("time", time, "values", data);
end

function values = localInterp(series, time)
values = interp1(series.time, series.values, time, "linear", "extrap");
values = values(:);
end

function row = localEmptyScenario
row = struct("id", "", "requested_inputs", struct, ...
    "simulation_wall_clock_s", NaN, "simulation_pass", false, ...
    "required_evidence_pass", false, "valid", false, ...
    "outputs", struct, "metrics", struct, "error", struct);
end

function count = localValidCount(rows)
if isempty(rows), count = 0; else, count = sum([rows.valid]); end
end

function localRestore(originalDir, originalPath)
localCloseAll;
try, cd(originalDir); catch, end
try, path(originalPath); catch, end
end

function localCloseAll
models = string(find_system("type", "block_diagram"));
for model = models(:)', try, close_system(model, 0); catch, end, end
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function value = localNow
value = string(datetime("now", "TimeZone", "UTC", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"));
end

function value = localError(ME)
value = struct("identifier", string(ME.identifier), "message", string(ME.message), ...
    "report", string(getReport(ME, "extended", "hyperlinks", "off")));
end

function localWriteJson(path, value)
text = jsonencode(value, "PrettyPrint", true);
fid = fopen(path, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XMED09:Write", "Cannot write %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fprintf(fid, "%s\n", text);
end

